// Generated by tools/gen_quest_voices.py from src/narration-quests-text.json (ajan:quests). Do not edit by hand.
// Adds story/quest lines to BABA.Narration (tr-TR-AhmetNeural) and BABA.NarrationEN (en-US-SteffanNeural).
window.BABA = window.BABA || {};
(function (B) {
  B.Narration = B.Narration || {}; B.NarrationEN = B.NarrationEN || {};
  var TR = {"story1":{"text":"İlk adın ardından bütün gece ellerini yıkadın. Yirminci yılında yalnız kalemin ucunu temizliyordun. Cellat bedeni kesti; hükmü sen yazdın. Kuyunun karanlığı cezanın bittiği yer değil. Yazdıklarının seni tanıdığı yer.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":19.27,"chapter":1,"audio":""},"truth1":{"text":"Cellat son nefesinde fısıldıyor: Sen yazdın, ben kestim. Beni öldürdün, kâtip. Yazdığın adlar hâlâ yaşıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":10.876,"chapter":1,"audio":""},"rescue1":{"text":"Derviş yemin taşına ulaştı. Adını sen yazmıştın; o yine de sana matarasını bıraktı.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.46,"chapter":1,"audio":""},"hunt1":{"text":"Kefen Dokuyucu düştü. Dokuduğu kefenlerin hiçbiri ölüler için değildi.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.29,"chapter":1,"audio":""},"pages1":{"text":"Üç sayfa, aynı el. İlkinde bir görev, ikincisinde paylaşılan bir suç, sonuncusunda Selvi'nin adı. Hiçbir satırda kalemi bırakmadın.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":12.111,"chapter":1,"audio":""},"story2":{"text":"Yüz yirmi adı tek bir satıra sığdırdın: borç ödendi. Tekneler boş döndüğünde kıyıda kalan ayakkabıları saymadın. Şimdi her çan sesi o son nefesi geri getiriyor. Selvi de bu yoldan geçti. Onun adını sayılardan ayırmak, ötekileri unutmana izin vermez.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":21.96,"chapter":2,"audio":""},"truth2":{"text":"Çancı susmadan önce bir ad söylüyor: Selvi. Boğulmadı. Krala verdim. Bu kıyının borcunu onunla ödedim.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":11.303,"chapter":2,"audio":""},"rescue2":{"text":"Kerem fenere ulaştı. Babası çanı ağlayarak çalmıştı. Kıyıda ilk kez biri, dönenler için dua ediyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":10.03,"chapter":2,"audio":""},"hunt2":{"text":"Tuz İçindeki Yeminli düştü. Tuz çatlarken içinden bir anahtar ve bir tekne kaydı döküldü.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.52,"chapter":2,"audio":""},"pages2":{"text":"Selvi senden yalnız bir şey istedi: Abi, adımı sen yazma. Altında senin imzan var. Kıyının tuzu onu silemedi.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":10.685,"chapter":2,"audio":""},"story3":{"text":"Kral sana temiz bir kalem verdi; temiz kalacağını hiç söylemedi. Tahtını korumak için kendi adını sattı, sen hayatını korumak için başkalarının adını yazdın. Taşın içindeki nefesler bunu biliyor. İkinizin de üstünde aynı mühür var: Kara Kadı'nın mührü.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":20.415,"chapter":3,"audio":""},"truth3":{"text":"Tahtın altından kralın sesi geliyor: Adımı sattım, hükmümü değil. Defter Kara Kadı'nın. Beni düşürmen onun satırını silmez.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":11.311,"chapter":3,"audio":""},"rescue3":{"text":"Kör taşçı, yazdığın her adı mezar taşına oymuştu. Şimdi senin adının üstünü çizdi.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.27,"chapter":3,"audio":""},"hunt3":{"text":"Kehanetçi Ulvi düştü. Son kehaneti: Kâtip, kendi adını kendi eliyle yazacak.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.32,"chapter":3,"audio":""},"pages3":{"text":"Kralın emrinin altında Kadı'nın mührü var. Yazmayı reddedersen kendi adın yazılacak, diri gömüleceksin. Tehdit gerçekti. Yazdığın insanlar da gerçekti.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":14.388,"chapter":3,"audio":""},"story4":{"text":"Her ad bir halka oldu. Her halka, ateşin içinde bitmeyen bir gün. Sen satırları çoğalttıkça ocak mahkûmların soluğunu çekti. Şimdi Selvi'nin halkasını arıyorsun. Bulacağın şeyin seni aklamasını bekleme. Onun adının başında da senin imzan var.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":22.646,"chapter":4,"audio":""},"truth4":{"text":"Küllerde Selvi'nin halkası var. İçi boş. O yanmadı; Kadı onu yazı masasına bağladı. Ateş sustu. Mürekkep akıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":13.15,"chapter":4,"audio":""},"rescue4":{"text":"Yusuf bin halka dövdü. Şimdi senin kılıcını dövüyor, bin halkanın bedeli olsun diye.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.85,"chapter":4,"audio":""},"hunt4":{"text":"Kül Veziri düştü. Kadı'ya giden yol cübbesine dikilmiş: mürekkepten bir nehir ve sonsuz raflar.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.75,"chapter":4,"audio":""},"pages4":{"text":"Halka hesabında bir satır eksik. Kadı, senin elin durduğunda başka bir el aramış. Yanık itirafında korkunu yazmışsın; boş bıraktığın satırda şimdi kendi adın bekliyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":13.654,"chapter":4,"audio":""},"story5":{"text":"Selvi'nin adını yazdığında elin titremedi. Korkuyu çoktan alışkanlığa çevirmiştin. Sonra Defter'i yakmaya çalıştın; bir ad silinmeden bir el değişti. Şimdi kardeşin senin harflerini yazıyor. Onu buradan çıkarırken yerine kimi bırakacağını düşün. Kadı'nın son tuzağı bu.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":23.887,"chapter":5,"audio":""},"ch5Intro":{"text":"Selvi senin el yazını öğrenmiş. Kadı'nın aradığı yeni bir kâtip değil; aynı suçu yeniden işleyecek bir el.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.487,"chapter":5,"audio":""},"ch5Checkpoint":{"text":"Yemin taşı son kez adını hatırlıyor. Ötesi, mührün salonu.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.8,"chapter":5,"audio":""},"ch5Boss":{"text":"Kara Kadı. Bütün hükümleri o mühürledi. Onun mührünü kır.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.98,"chapter":5,"audio":""},"ch5Win":{"text":"Kadı'nın mührü kırıldı. Kalem senin elinde. Son satıra ne yazacaksın?","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.64,"chapter":5,"audio":""},"ch5Death":{"text":"Defter adını yazmaya hazırlanıyor. Daha değil. Kalk.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.41,"chapter":5,"audio":""},"questSeals":{"text":"Efendilerin mühürleri yerinde. Defter'in kilidi çözüldü.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.36,"chapter":5,"audio":""},"questSelvi":{"text":"Selvi'nin kararını verdin. Kalem artık onun elinde değil.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.4,"chapter":5,"audio":""},"selviFreed":{"text":"Selvi kalemi bırakıyor. Abi, diyor. Adımı sen yazdın, biliyorum. Yine de geldin.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":10.13,"chapter":5,"audio":""},"hunt5":{"text":"Mürekkep Cellatı düştü. Kanı siyah değil; yalnızca mürekkep.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.84,"chapter":5,"audio":""},"pages5":{"text":"Son sayfada elin sakin. Selvi'nin adı açık, imzan sağlam. Kadı seni geri getirmek için satırı boş bıraktı. Seni burada tutan şey yalnız Kadı'nın hükmü değil. Altındaki imzan.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":17.38,"chapter":5,"audio":""},"endingName":{"text":"Bu kez kendi adını yazıyorsun. Zincirler birer birer düşerken kabirler ilk kez sessiz. Toprak ağzını dolduruyor; yeniden nefes almaya çalışmıyorsun. Selvi gün ışığına çıkıyor. Seni bağışladığını söylemiyor. Adını unutmuyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":22.127,"chapter":5,"audio":""},"endingBurn":{"text":"Defter'i ateşe veriyorsun. Adları taşıyanlar özgür kalıyor; fakat annelerini, evlerini, kendi yüzlerini hatırlamıyorlar. Selvi sana bir yabancı gibi bakıyor. Sen her harfi hatırlıyorsun. Mahkûmları kendi pişmanlığından çıkardın. O pişmanlığın içinde yalnız kaldın.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":24.298,"chapter":5,"audio":""},"endingQuill":{"text":"Selvi'nin adını siliyorsun. Kapı onun için açılıyor. Kalem avucuna gömülürken ilk boş satır yeniden beliriyor. Birini kurtarmak için bir başkasını yazacağını söylüyorsun. Yirmi yıl önce de böyle başlamıştın. Kara Kadı öldü. Elin hâlâ yazıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":24.256,"chapter":5,"audio":""},"leanMercy":{"text":"Bıraktığın ölüler arkandan fısıldıyor: bu kâtip başka. Merhamet, Defter'in tanımadığı bir mürekkep.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.45,"chapter":0,"audio":""},"leanWrath":{"text":"Hükmün keskinleşiyor, Bahtiyar. Yargıladıkça, mühür basan o ele benziyorsun.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.36,"chapter":0,"audio":""}};
  var EN = {"story1":{"text":"After the first name, you washed your hands all night. By your twentieth year, you cleaned only the nib. The Executioner cut the body; you wrote the sentence. The well's darkness is not where punishment ends. It is where those you condemned recognize you.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":19.216,"chapter":1,"audio":""},"truth1":{"text":"With his last breath, the Executioner whispers: You wrote, I cut. You killed me, scribe. The names you wrote are still alive.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":9.893,"chapter":1,"audio":""},"rescue1":{"text":"The dervish has reached the oath stone. You wrote his name, and still he left you his flask.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.41,"chapter":1,"audio":""},"hunt1":{"text":"The Shroud Weaver has fallen. None of the shrouds she wove were meant for the dead.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":6.13,"chapter":1,"audio":""},"pages1":{"text":"Three pages, one hand. A duty on the first, a shared crime on the second, Selvi's name on the last. In none of those lines did you put down the pen.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":11.826,"chapter":1,"audio":""},"story2":{"text":"You reduced a hundred and twenty names to one line: debt paid. When the boats returned empty, you did not count the shoes left on shore. Now every toll returns that final breath. Selvi passed this way too. Finding her name among the numbers does not permit you to forget the others.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":20.782,"chapter":2,"audio":""},"truth2":{"text":"Before the Bellringer falls silent, he speaks a name: Selvi. She did not drown. I gave her to the King. I paid this shore's debt with her.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":11.25,"chapter":2,"audio":""},"rescue2":{"text":"Kerem has reached the lantern. His father wept as he rang the bell. For the first time, someone on this shore prays for those who returned.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":11.39,"chapter":2,"audio":""},"hunt2":{"text":"The Salt-Sworn has fallen. As the salt cracked, a key and a boat log spilled out.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.03,"chapter":2,"audio":""},"pages2":{"text":"Selvi asked only one thing of you: Brother, don't you write my name. Your signature lies beneath it. The shore's salt could not erase it.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":9.981,"chapter":2,"audio":""},"story3":{"text":"The King gave you a clean pen; he never promised it would stay clean. He sold his name to keep his throne. You wrote other names to keep your life. The breaths trapped in stone know it. The same seal lies over you both: the Black Judge's seal.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":17.96,"chapter":3,"audio":""},"truth3":{"text":"The King's voice rises from beneath the throne: I sold my name, not my sentence. The Ledger belongs to the Black Judge. My fall does not erase his line.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":12.026,"chapter":3,"audio":""},"rescue3":{"text":"The blind mason carved every name you wrote onto a gravestone. Now he has struck yours through.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.36,"chapter":3,"audio":""},"hunt3":{"text":"Ulvi the seer has fallen. His last prophecy: the scribe will write his own name with his own hand.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":8.37,"chapter":3,"audio":""},"pages3":{"text":"The Judge's seal lies beneath the King's order. Refuse to write, and your own name will be written. You will be buried alive. The threat was real. So were the people you condemned.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":13.747,"chapter":3,"audio":""},"story4":{"text":"Each name became a link. Each link became a day in the fire that never ends. As your lines multiplied, the furnace drew the prisoners' breath. Now you seek Selvi's link. Do not expect what you find to absolve you. Her name bears your signature too.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":18.698,"chapter":4,"audio":""},"truth4":{"text":"Selvi's link lies in the ash. It is empty. She did not burn; the Judge chained her to a writing desk. The fire is silent. The ink still flows.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":13.142,"chapter":4,"audio":""},"rescue4":{"text":"Yusuf forged a thousand links. Now he forges your blade, to pay for every one of them.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.52,"chapter":4,"audio":""},"hunt4":{"text":"The Ash Vizier has fallen. The road to the Judge is stitched into his robe: a river of ink, and endless shelves.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":9.18,"chapter":4,"audio":""},"pages4":{"text":"A line is missing from the link account. When your hand stopped, the Judge sought another. You wrote your fear in a burned confession; now your own name waits in the line left empty.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":12.415,"chapter":4,"audio":""},"story5":{"text":"Your hand did not tremble when you wrote Selvi's name. You had long made fear a habit. Then you tried to burn the Ledger; before one name was erased, one hand replaced another. Now your sister writes your letters. Think who you will leave behind when you bring her out. That is the Judge's last trap.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":22.02,"chapter":5,"audio":""},"ch5Intro":{"text":"Selvi has learned your handwriting. The Judge does not need a new scribe; he needs a hand that will commit the same crime again.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":8.465,"chapter":5,"audio":""},"ch5Checkpoint":{"text":"The oath stone remembers your name one last time. Beyond lies the hall of the seal.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":6.4,"chapter":5,"audio":""},"ch5Boss":{"text":"The Black Judge. He sealed every sentence. Break his seal.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":6,"chapter":5,"audio":""},"ch5Win":{"text":"The Judge's seal is broken. The pen is in your hand. What will you write on the last line?","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.65,"chapter":5,"audio":""},"ch5Death":{"text":"The Ledger is ready to write your name. Not yet. Rise.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":6.09,"chapter":5,"audio":""},"questSeals":{"text":"The masters' seals are in place. The Ledger's lock is broken.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.28,"chapter":5,"audio":""},"questSelvi":{"text":"You have decided Selvi's fate. The pen is no longer in her hand.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.78,"chapter":5,"audio":""},"selviFreed":{"text":"Selvi lets go of the pen. Brother, she says. You wrote my name, I know. Still, you came.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":8.72,"chapter":5,"audio":""},"hunt5":{"text":"The Ink Headsman has fallen. His blood is not black. It is only ink.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":6.83,"chapter":5,"audio":""},"pages5":{"text":"On the last page, your hand is steady. Selvi's name is clear. Your signature is firm. The Judge left one line empty to bring you back. It is not only his sentence that binds you here. It is your signature beneath it.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":17.58,"chapter":5,"audio":""},"endingName":{"text":"This time, you write your own name. One by one the chains fall, and for the first time the graves are silent. Earth fills your mouth; you no longer struggle for breath. Selvi steps into daylight. She does not say she forgives you. She does not forget your name.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":20.101,"chapter":5,"audio":""},"endingBurn":{"text":"You set the Ledger alight. Those bound to its names go free, but they remember neither their mothers, their homes, nor their own faces. Selvi looks at you as a stranger. You remember every letter. You freed the prisoners from your remorse. You are left alone inside it.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":20.215,"chapter":5,"audio":""},"endingQuill":{"text":"You erase Selvi's name. The door opens for her. As the pen sinks into your palm, the first empty line appears again. You tell yourself you will write another name to save one person. That was how it began twenty years ago. The Black Judge is dead. Your hand is still writing.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":21.412,"chapter":5,"audio":""},"leanMercy":{"text":"The dead you spared whisper behind you: this scribe is different. Mercy is an ink the Ledger does not know.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":8.3,"chapter":0,"audio":""},"leanWrath":{"text":"Your judgment grows sharper, Bahtiyar. The more you judge, the more you resemble the hand that stamps the seal.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":8.5,"chapter":0,"audio":""}};
  Object.keys(TR).forEach(function (k) { if (!B.Narration[k]) B.Narration[k] = TR[k]; });
  Object.keys(EN).forEach(function (k) { if (!B.NarrationEN[k]) B.NarrationEN[k] = EN[k]; });
})(window.BABA);
